import numpy as np

class SemanticCache:
    def __init__(self, embed_fn, threshold=0.92):
        self.embed_fn = embed_fn
        self.threshold = threshold
        self.entries = []  # list of (embedding, query, answer)

    def lookup(self, query):
        query_emb = self.embed_fn(query)
        for emb, cached_query, answer in self.entries:
            similarity = np.dot(query_emb, emb) / (np.linalg.norm(query_emb) * np.linalg.norm(emb))
            if similarity >= self.threshold:
                return answer
        return None

    def store(self, query, answer):
        self.entries.append((self.embed_fn(query), query, answer))
